"""Report diagnostic, candidate definition, local gate and failed global criterion."""
from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parents[2];F=ROOT/'docs/verification'
def read(n):return json.loads((F/n).read_text())
def digest(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
    energy=read('q9-distorted-energy-result.json');ea=read('q9-distorted-energy-artifact-audit.json');gate=read('q9-shear-projection-gate-result.json');ga=read('q9-shear-projection-gate-audit.json')
    baseline=read('q9-distorted-plate-result.json');candidate=read('q9-shear-projection-plate-result.json');audit=read('q9-shear-projection-plate-artifact-audit.json');same=read('q9-shear-projection-same-reference-diagnostic.json')
    assert energy['all_criteria_pass'] and ea['all_criteria_pass'] and gate['all_criteria_pass'] and ga['all_criteria_pass']
    assert not candidate['all_criteria_pass'] and not audit['all_criteria_pass'] and not audit['experiment_acceptance_pass']
    lines=['# Q9成分診断とP-S36比較：結果・採用判断','','2026-10-31。**横せん断投影P-S36単独では、事前の薄肉一様性基準を満たさない。製品の主シェルへ採用する判断は見送る。** 既存の完全積分Q9の不合格結果も維持する。','','## 1. 成分診断','','[事前仕様](q9-distorted-energy-experiment.md) に従い、保存済み8平衡場について、正の二次形式a=2Uを面内偶次・面内奇次・厚さ法線残差・横せん断へ分解した。法線のPoisson結合は平方完成に含める。面内偶次を一般シェルの膜エネルギー全体とは呼ばない。','','[結果](q9-distorted-energy-result.json) と [別の物理勾配評価による監査](q9-distorted-energy-artifact-audit.json) は成立。保存場の仕事、参照解・誤差の恒等式、9／11点積分、偶奇分離を確認した。これは変更前の適合モデルの結果で、投影後に同じGalerkin恒等式を無条件には課さない。','','| 厚さ | 分割 | 誤差二次形式／参照J | 面内奇次の内訳 | 厚さ法線残差の内訳 | 横せん断の内訳 |','|---:|---:|---:|---:|---:|---:|']
    for c in energy['cases']:
        s=c['shares']['error'];lines.append(f"| {c['h']} | {c['n']} | {sum(c['normalized']['error'].values()):.8g} | {100*s['plane_odd']:.3f}% | {100*s['thickness_residual']:.3f}% | {100*s['transverse_shear']:.3f}% |")
    lines += ['', '面内偶次の誤差寄与は今回ほぼ0。問題となったn=8・厚さ0.001では横せん断が約68.6%、面内奇次が約27.5%、厚さ法線残差が約3.9%だった。これは誤差の正の内訳で、横せん断だけが原因だと証明するものではない。参照を節点で補間した場も平衡解とは分けて記録した。', '', '## 2. 定式化した比較候補','','[P-S36の式・処理契約](../q9-shear-projection-candidate.md) に、共変横せん断のQ12／Q21×厚さP2空間、36局所係数、μ重み付き投影、固定参照Gram行列、鞍点汎関数、局所消去、内力と一貫接線、キャッシュ・失敗条件を定義した。公刊MITC9と同一の方式とは称さない。','','[局所ゲート](q9-shear-projection-gate-result.json) は矩形・斜交・台形で11条件全て成立。M正定値、閾値3種でrank75、剛体6モード、6一定ひずみと純曲げの内力、エネルギー順序、別消去との一致、重複列の拒否を確認した。[独立な行列再計算の監査](q9-shear-projection-gate-audit.json) も成立した。局所の良好な結果だけで大域収束や製品適格性を保証しない。','','## 3. 同じ8ケースでの大域比較','','[大域比較仕様](q9-shear-projection-plate-experiment.md) の荷重・支持・格子・精度基準を固定し、横せん断項だけを変更した。7／9点組立、70／90桁保持解など8ケースの数値処理の必須条件は成立。下表はL2誤差。','','| 厚さ | 分割 | 元の完全積分Q9 | P-S36 |','|---:|---:|---:|---:|']
    for c in candidate['cases']:
        b=next(r for r in baseline['cases'] if r['n']==c['n'] and r['h']==c['h'])
        lines.append(f"| {c['h']} | {c['n']} | {100*b['observables']['l2_relative']:.6f}% | {100*c['observables']['l2_relative']:.6f}% |")
    lines += ['', '最細16×16では両厚さの中央たわみ・L2・コンプライアンスが全て1%以内。最後のL2次数は厚さ0.01で3.37618、0.001で3.17497。しかしn=8の薄肉／中厚L2比は約8.042で、既定の2倍＋1e−8を超えた。元の約4.122より比が増えても、絶対誤差は両厚さとも改善している。この二つを混同せず、必須基準の未達を維持する。','','[主結果](q9-shear-projection-plate-result.json) のall_criteria_passはfalse。閾値・誤差分母・格子を変更して合格にしない。','','## 4. 独立観測監査の未達と切分け','','[独立観測監査](q9-shear-projection-plate-artifact-audit.json) もall_criteria_pass=falseで保存した。別7点厚さで計算した4変数参照の微小な評価差が、薄肉最細の小さなL2誤差に対する照合基準を超えた。L2絶対差は約2.10e−11、相対差約2.82e−8で、監査基準1e−8を満たさない。精度・次数・薄肉一様性の合否自体は同じだが、監査全体を合格とはしない。', '',f"事後の [同じ参照値を固定した診断](q9-shear-projection-same-reference-diagnostic.json) では、別形状関数・11点積分とのL2相対差は最大{max(r['same_reference_relative_difference'] for r in same['cases']):.6e}だった。観測処理と独立参照の評価感度を分けるための診断で、元の監査条件や未達を置き換えない。独立参照は許容されていた係数差が、小さな誤差量の照合へどう伝播するかを次の参照契約で閉じる必要がある。",'', '局所監査の初回は積分次数の不一致（主9点対別経路7点を同次数の許容差で比較）を修正し、元9点同士で一致を確認した。大域監査の初回の参照ソース名も修正した。修正前の [局所記録](q9-shear-projection-gate-audit-initial.json)・[大域記録](q9-shear-projection-plate-audit-initial.json) を残す。要素・主実験結果・判定しきい値は変更していない。','','## 5. 確定した判断と残作業','','- 成分診断は、横せん断を優先して検討する根拠となった。横せん断だけを変更する候補の比較でも、薄肉一様性の必須基準は閉じなかった。P-S36の製品採用への昇格は見送る。','- 次の候補を試す前に、無せん断場の局所／共有自由度への適合と、投影が勾配を保存する条件を審査する。膜・厚さ法線を含む他成分を、観測内訳だけで無関係としない。','- 4変数参照の入力精度・求解精度・係数の保持・誤差指標への感度の契約を定める。独立参照の丸め差を要素の誤差へ混ぜず、元監査を後付けで合格にしない。','- 今回の局所候補が未審査の一般曲面・異方材・積層・非線形接線・厚さ再表現を、平坦等方材の結果で代替しない。ST-01/04、構造審査全体、J1、製品コア開始は未完了。','']
    (F/'q9-shear-projection-results.md').write_text('\n'.join(lines),encoding='utf-8')
    evidence=['q9-distorted-energy-result.json','q9-distorted-energy-artifact-audit.json','q9-shear-projection-gate-result.json','q9-shear-projection-gate-audit.json','q9-shear-projection-plate-result.json','q9-shear-projection-plate-artifact-audit.json','q9-shear-projection-same-reference-diagnostic.json','q9-shear-projection-results.md']
    record=dict(source_sha256=digest(__file__),evidence_sha256={n:digest(F/n) for n in evidence},energy_diagnostic_pass=True,local_gate_pass=True,
        global_experiment_pass=False,global_observation_audit_pass=False,product_shell_adopted=False,decision='P-S36 alone not adopted; thin-uniformity and reference-metric audit remain unmet')
    (F/'q9-shear-projection-disposition.json').write_text(json.dumps(record,indent=2)+'\n')
if __name__=='__main__':main()
